def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def maxLength(nums: List[int]) -> int:
    max_length = 0
    n = len(nums)

    for start in range(n):
        prime_count = {}
        for end in range(start, n):
            num = nums[end]
            for p in [2, 3, 5, 7]:
                if num % p == 0:
                    if p in prime_count:
                        prime_count[p] += 1
                    else:
                        prime_count[p] = 1

            if (end - start + 1) > 2 and any(count > 1 for count in prime_count.values()):
                break

            max_length = max(max_length, end - start + 1)

    return max_length

