def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            result.extend(grid[i])  # Traverse right in even rows
        else:
            result.extend(grid[i][::-1])  # Traverse left in odd rows
    return [result[j] for j in range(len(result)) if j % 2 == 0]  # Skip every alternate element

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:  # Check if adjacent digits are different
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if counts[s[i]] == first_digit and counts[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]
    return ""

def maxDifference(s: str) -> int:
    from collections import Counter
    counts = Counter(s)
    odd_freqs = [count for count in counts.values() if count % 2 != 0]
    even_freqs = [count for count in counts.values() if count % 2 == 0]
    return max(odd_freqs) - min(even_freqs)

