def totalNumbers(digits: List[int]) -> int:
    count = 0
    digits_set = set(digits)
    even_digits = [d for d in digits_set if d % 2 == 0]
    for last_digit in even_digits:
        for first_digit in digits_set:
            if first_digit == 0:
                continue
            for second_digit in digits_set:
                if first_digit == second_digit and digits.count(first_digit) < 2:
                    continue
                if last_digit == first_digit and digits.count(last_digit) < 2:
                    continue
                if last_digit == second_digit and digits.count(last_digit) < 2:
                    continue
                count += 1
    return count // 6

