def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return n
    dp = [1] * n  # dp[i] will hold the length of longest subsequence ending at index i
    max_length = 1

    for i in range(1, n):
        for j in range(i):
            diff1 = abs(nums[i] - nums[j])
            # Check if we can extend the subsequence from j to i
            if dp[j] > 0:
                valid = True
                for k in range(j):
                    diff2 = abs(nums[j] - nums[k])
                    if diff1 < diff2:
                        valid = False
                        break
                if valid:
                    dp[i] = max(dp[i], dp[j] + 1)
                    max_length = max(max_length, dp[i])

    return max_length

