def minCost(n: int, cost: List[List[int]]) -> int:
    if n == 2:
        return min(cost[0][0] + cost[1][1], cost[0][1] + cost[1][0], cost[0][2] + cost[1][0], cost[0][0] + cost[1][2], cost[0][1] + cost[1][2], cost[0][2] + cost[1][1])

    dp = [[0] * 3 for _ in range(n)]

    # Fill the dp array for the first half houses
    for j in range(3):
        dp[0][j] = cost[0][j]

    for i in range(1, n // 2):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])

    first_half_cost = [dp[i] for i in range(n // 2)]

    # Fill the dp array for the second half houses
    dp = [[0] * 3 for _ in range(n)]

    for j in range(3):
        dp[n-1][j] = cost[n-1][j]

    for i in range(n - 2, n // 2 - 1, -1):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i + 1][(j + 1) % 3], dp[i + 1][(j + 2) % 3])

    total_cost = float('inf')

    for color_first_half in range(3):
        for color_second_half in range(3):
            if color_first_half != color_second_half:
                total_cost = min(total_cost, first_half_cost[n//2-1][color_first_half] + dp[n-1][color_second_half])

    return total_cost

