def maxFrequency(nums: List[int], k: int) -> int:
    count = [0] * 51  # Since 1 <= nums[i], k <= 50
    for num in nums:
        count[num] += 1

    max_freq = 0
    for x in range(1, 51):
        if count[x] > 0:
            # Effect of converting x to k
            needed = k - x
            frequency = sum(count[i] for i in range(1, 51) if i + needed == k)
            if needed == 0:
                frequency += count[x]
            max_freq = max(max_freq, frequency)

    return max_freq

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    for i in range(len(s)):
        if s[i] == 'N':
            y += 1
        elif s[i] == 'S':
            y -= 1
        elif s[i] == 'E':
            x += 1
        elif s[i] == 'W':
            x -= 1
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)
        distance_with_changes = min(i + 1, current_distance + 2 * k)
        max_distance = max(max_distance, distance_with_changes)
    return max_distance
